item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic       clk,
    input  logic       x,
    input  logic [2:0] y,
    output logic       Y0,
    output logic       z
);
    always_comb begin
        Y0 = 1'b0;
        z  = 1'b0;
        case (y)
            3'b000: Y0 = x;
            3'b001: Y0 = ~x;
            3'b010: Y0 = x;
            3'b011: begin
                Y0 = ~x;
                z  = 1'b1;
            end
            3'b100: begin
                Y0 = ~x;
                z  = 1'b1;
            end
            default: begin
                Y0 = 1'b0;
                z  = 1'b0;
            end
        endcase
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic clk, x;
    logic [2:0] y;
    wire Y0, z;
    logic [2:0] expected_next;
    logic expected_z;
    integer s, b, c;
    integer checks = 0;
    TopModule dut (.clk(clk), .x(x), .y(y), .Y0(Y0), .z(z));
    initial begin
        for (s = 0; s < 8; s = s + 1) begin
            for (b = 0; b < 2; b = b + 1) begin
                for (c = 0; c < 2; c = c + 1) begin
                    y = s[2:0]; x = b[0]; clk = c[0];
                    expected_next = 3'"'b000;
                    expected_z = 1'b0;
                    case (s)
                        0: expected_next = b ? 3'b001 : 3'b000;
                        1: expected_next = b ? 3'b100 : 3'b001;
                        2: expected_next = b ? 3'b001 : 3'b010;
                        3: begin
                            expected_next = b ? 3'b010 : 3'b001;
                            expected_z = 1'b1;
                        end
                        4: begin
                            expected_next = b ? 3'b100 : 3'b011;
                            expected_z = 1'b1;
                        end
                    endcase
                    #1;
                    if (Y0 "'!== expected_next[0] || z !== expected_z)
                        $fatal(1, "FAIL y=%b x=%b clk=%b Y0=%b z=%b", y, x, clk, Y0, z);
                    checks = checks + 1;
                end
            end
        end
        $display("PASS: %0d combinations checked", checks);
        $finish;
    end
    initial begin
        #100;
        $fatal(1, "FAIL timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1'

